text = input()

cleaned = ""
for ch in text:
    if ch.isalnum():
        cleaned += ch.lower()

print("Cleaned:", cleaned)
if cleaned == cleaned[::-1]:
    print("Palindrome")
else:
    print("Not a palindrome")

def shift_text(text, k):
    result = ""
    for ch in text:
        if ch.isupper():
            result += chr((ord(ch) - ord("A") + k) % 26 + ord("A"))
        elif ch.islower():
            result += chr((ord(ch) - ord("a") + k) % 26 + ord("a"))
        else:
            result += ch
    return result


text = input()
k = int(input())

encrypted = shift_text(text, k)
decrypted = shift_text(encrypted, -k)

print("Encrypted:", encrypted)
print("Decrypted:", decrypted)

a, b, c = map(int, input().split())

if a <= 0 or b <= 0 or c <= 0 or a + b <= c or a + c <= b or b + c <= a:
    print("Not a triangle")
else:
    if a == b == c:
        print("Equilateral")
    elif a == b or b == c or a == c:
        print("Isosceles")
    else:
        print("Scalene")

    x, y, z = sorted([a, b, c])
    if x * x + y * y == z * z:
        print("Right-angled")
    else:
        print("Not right-angled")

n = int(input())

for i in range(1, 11):
    print(f"{n} x {i} = {n * i}")

words = input().split()

freq = {}
for w in words:
    freq[w] = freq.get(w, 0) + 1

best = words[0]
for w in freq:
    if freq[w] > freq[best]:
        best = w

print("Frequency:", freq)
print("Most frequent:", best)

words = input().split()

groups = {}
for w in words:
    key = "".join(sorted(w))
    if key not in groups:
        groups[key] = []
    if w not in groups[key]:
        groups[key].append(w)

for members in groups.values():
    print(" ".join(members))
print("Groups:", len(groups))

def calculate(a, b, operation):
    return operation(a, b)


operations = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "max": lambda a, b: a if a > b else b,
    "min": lambda a, b: a if a < b else b,
    "pow": lambda a, b: a ** b,
}

a, b = map(int, input().split())
names = input().split()

for name in names:
    if name in operations:
        print(f"{name}: {calculate(a, b, operations[name])}")
    else:
        print(f"{name}: Unsupported")

